INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (0, 72, 1, 0, 0, 10, "直感、あったんですよね。\nアオイさんほど詳しくはないですが、\nわたしも草花が好きなので。\nこの人とは仲良くなれそう、みたいな。", 11, 1, 1, 72017);
INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES ("", 72, 0, "", "", 0, "", 91, "", 0, 72018);
