INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (0, 72, 1, 0, 0, 10, "だからわたし、\n勇気を出して言ってみたんです！\nお友だちになりませんか、って。", 11, 1, 1, 72021);
INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES ("", 72, 0, "", "", 0, "", 91, "", 0, 72022);
